"""Build local analytics reference dashboards for the uncatalogued research opportunities."""
from pathlib import Path
import csv,json,random,datetime
ROOT=Path(__file__).resolve().parent/'opportunity-demos'
PROJECTS=[
('11-overdue-collections','Overdue Collections','Collections','Invoice balance','Outstanding PKR','Invoice','Days overdue','> 30 days',120000,'collection'),
('12-job-profitability','Job Profitability','Jobs','Job revenue','Revenue PKR','Job type','Cost overrun','Over budget',260000,'profit'),
('13-budget-forecasting','Budget & Forecasting','Periods','Actual spend','Spend PKR','Department','Variance','Over budget',420000,'budget'),
('14-manufacturing-waste','Manufacturing Waste','Work orders','Material waste','Waste cost PKR','Product line','Reject rate','Above 3%',78000,'waste'),
('15-construction-analytics','Construction Project Analytics','Projects','Earned value','Earned value PKR','Project manager','Schedule variance','Behind plan',880000,'construction'),
('16-demand-planning','Demand Planning','SKU periods','Forecast error','Units','Category','Stock risk','Short cover',90,'demand'),
('17-multi-branch','Multi-branch Performance','Branch periods','Net sales','Net sales PKR','Branch','Target gap','Below target',640000,'branch'),
('18-marketing-analytics','Marketing Analytics','Campaigns','Attributed revenue','Revenue PKR','Channel','Return on ad spend','Below 2x',250000,'marketing'),
('19-field-service-analytics','Field-service Analytics','Service jobs','Completed jobs','Jobs','Technician','SLA breach rate','Above 5%',34,'service'),
('20-business-central-reporting','Automated Reporting / Business Central','Ledger periods','Operating balance','Net amount PKR','Account group','Reconciliation status','Review',135000,'ledger'),
('21-power-bi-repair-toolkit','Dashboard Repair / Rebuild Toolkit','Report checks','Readiness score','Score / 100','Check area','Issues','Needs repair',12,'repair')]
GROUPS={
'collection':['Retail','Workshop','Fleet','Corporate'],'profit':['Install','Consulting','Maintenance','Fabrication'],'budget':['Operations','Sales','People','Technology'],'waste':['Assembly','Paint','Press','Packaging'],'construction':['Tower A','Road Lot 3','Warehouse','Utilities'],'demand':['Parts','Fluids','Electrical','Safety'],'branch':['Karachi','Lahore','Islamabad','Rawalpindi'],'marketing':['Search','Social','Email','Partners'],'service':['Karachi team','Lahore team','North team','Central team'],'ledger':['Revenue','Direct costs','Payroll','Overheads'],'repair':['Data model','Measures','Relationships','Report layout']}
ITEMS={
'collection':['INV-1042','INV-1068','INV-1104','INV-1117'],'profit':['JOB-024','JOB-028','JOB-031','JOB-036'],'budget':['FY26-M01','FY26-M02','FY26-M03','FY26-M04'],'waste':['WO-2081','WO-2092','WO-2138','WO-2190'],'construction':['PRJ-014','PRJ-018','PRJ-021','PRJ-027'],'demand':['SKU-0102','SKU-0134','SKU-0208','SKU-0311'],'branch':['2026-W19','2026-W20','2026-W21','2026-W22'],'marketing':['CMP-Search','CMP-Social','CMP-Email','CMP-Partner'],'service':['SV-9041','SV-9083','SV-9150','SV-9218'],'ledger':['GL-4000','GL-5100','GL-6200','GL-7100'],'repair':['CHK-01','CHK-02','CHK-03','CHK-04']}
BASE=['period','group','item','status','actual','cost','target','units','extra']
HTML=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>__TITLE__ · Analytics</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6f5;color:#18332d;font:14px system-ui,sans-serif}header{background:#0d342e;color:white;padding:25px max(20px,calc((100% - 1250px)/2))}header small{color:#9ac7b6;text-transform:uppercase;letter-spacing:1px}h1{margin:8px 0}header p{margin:0;color:#c6d8d1}.wrap{max-width:1250px;margin:auto;padding:22px}.filters,.toolbar{display:flex;gap:10px;align-items:center;margin-bottom:16px;flex-wrap:wrap}select,input,button,a{font:inherit;padding:10px;border-radius:7px;border:1px solid #d9e3df;background:white;color:#153b33}button{cursor:pointer}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:13px}.card,.panel{background:white;border:1px solid #e0e7e4;border-radius:11px;padding:17px}.card small,.muted{color:#647a71}.card b{display:block;font-size:24px;margin:8px 0}.row{display:grid;grid-template-columns:140px 1fr 85px;gap:12px;align-items:center;margin:14px 0}.track{background:#edf3f0;height:15px;border-radius:9px;overflow:hidden}.bar{height:100%;background:#21836d}.panels{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}h2{font-size:17px;margin:0 0 14px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;text-align:left}th,td{padding:11px;border-bottom:1px solid #edf1ef;white-space:nowrap}th{font-size:11px;color:#6a7f76;text-transform:uppercase}footer{font-size:12px;color:#697a73;margin-top:14px}@media(max-width:760px){.cards{grid-template-columns:1fr 1fr}.panels{grid-template-columns:1fr}.wrap{padding:13px}.row{grid-template-columns:90px 1fr 55px}}</style><header><small>POWER BI COLLECTION · ANALYTICS REFERENCE</small><h1>__TITLE__</h1><p>Interactive synthetic-data companion demo · PKR where amounts apply</p></header><main class="wrap"><div class="filters"><select id="group"><option value="">All __group_label__</option>__GROUPS__</select><select id="status"><option value="">All statuses</option>__STATUSES__</select><label class="muted">From <input id="from" type="month"></label><label class="muted">To <input id="to" type="month"></label><button id="csv">Export filtered CSV</button><span class="muted" id="count"></span></div><section class="cards" id="cards"></section><div class="panels"><section class="panel"><h2>__CHART_TITLE__ by __group_label__</h2><div id="chart"></div></section><section class="panel"><h2>Metric definitions</h2><p><b>__CARD1__:</b> __DEF1__</p><p><b>__CARD2__:</b> __DEF2__</p><p><b>__CARD3__:</b> __DEF3__</p><p class="muted">Demo data is fictional. Connect and reconcile against source systems before business use.</p></section></div><section class="panel" style="margin-top:14px"><h2>Detail rows</h2><div class="scroll"><table><thead><tr>__HEADERS__</tr></thead><tbody id="rows"></tbody></table></div></section><footer>Reference implementation, not a published Power BI report. This browser demo does not connect to Business Central or any customer data. Use the project’s README for model grain, KPI assumptions, and report-page outline.</footer></main><script>const D=__DATA__;const $=x=>document.getElementById(x);const money=n=>new Intl.NumberFormat('en-PK',{maximumFractionDigits:0}).format(+n||0);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function filtered(){return D.rows.filter(r=>(!$('group').value||r.group===$('group').value)&&(!$('status').value||r.status===$('status').value)&&(!$('from').value||r.period>=$('from').value)&&(!$('to').value||r.period<=$('to').value))}function render(){let rs=filtered(),sum=k=>rs.reduce((a,r)=>a+(+r[k]||0),0),act=sum('actual'),cost=sum('cost'),target=sum('target'),units=sum('units');let cards=D.cards.map(c=>({label:c.label,value:c.kind==='count'?rs.length:c.kind==='avg'?money(sum(c.key)/Math.max(1,rs.length)):c.kind==='ratio'?(sum(c.key)/Math.max(1,sum(c.denominator))).toFixed(2)+'x':c.kind==='percent'?(100*sum(c.key)/Math.max(1,sum(c.denominator))).toFixed(1)+'%':money(sum(c.key)),note:c.note}));$('cards').innerHTML=cards.map(c=>`<div class="card"><small>${esc(c.label)}</small><b>${esc(c.value)}</b><small>${esc(c.note)}</small></div>`).join('');let grouped={};rs.forEach(r=>grouped[r.group]=(grouped[r.group]||0)+Number(r.actual||0));let max=Math.max(1,...Object.values(grouped));$('chart').innerHTML=Object.entries(grouped).map(([g,v])=>`<div class="row"><span>${esc(g)}</span><div class="track"><div class="bar" style="width:${v/max*100}%"></div></div><b>${money(v)}</b></div>`).join('')||'<p class="muted">No rows under these filters.</p>';$('rows').innerHTML=rs.map(r=>`<tr>${D.columns.map(c=>`<td>${esc(c.format==='money'?money(r[c.key]):r[c.key])}</td>`).join('')}</tr>`).join('');$('count').textContent=rs.length+' rows'}['group','status','from','to'].forEach(id=>$(id).onchange=render);$('csv').onclick=()=>{let rs=filtered(),q=x=>'"'+String(x??'').replaceAll('"','""')+'"',out=[D.columns.map(c=>q(c.label)).join(','),...rs.map(r=>D.columns.map(c=>q(r[c.key])).join(','))].join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([out],{type:'text/csv'}));a.download=D.slug+'-demo.csv';a.click();URL.revokeObjectURL(a.href)};render();</script></html>'''

def main():
    for ix,(slug,title,plural,kpi,unit,group_label,kpi2,status_risk,base,kind) in enumerate(PROJECTS):
        rng=random.Random(8100+ix); groups=GROUPS[kind]; items=ITEMS[kind]; rows=[]; base_date=datetime.date(2026,1,1)
        for i in range(48):
            month=i%12+1; year=2025+i//12
            period=f'{year}-{month:02d}'; g=groups[i%len(groups)]; item=items[(i//4)%len(items)]
            target=base*(.70+rng.random()*.65); actual=target*(.65+rng.random()*.75); cost=actual*(.45+rng.random()*.48); units=max(1,int(actual/max(base*.03,1)))
            if kind=='demand':target=units*(.75+rng.random()*.5)
            status='On track'
            if kind=='collection': status=['Current','1–30 overdue','31–60 overdue','61+ overdue'][i%4]; actual=max(1000,target*(.2+rng.random()))
            if kind=='profit': status=['Complete','In progress','At risk','Complete'][i%4]
            if kind=='budget': status='Over budget' if actual>target else 'Within budget'
            if kind=='waste': status='Above 3%' if extra>3 else 'Within limit'
            if kind=='construction': status=['On schedule','Behind plan','Ahead','On schedule'][i%4]
            if kind=='demand': status=['Covered','Short cover','Excess','Covered'][i%4]; units=max(0,units)
            if kind=='branch': status='Below target' if actual<target else 'On target'
            if kind=='marketing': status='Below 2x' if actual/max(cost,1)<2 else 'On target'
            if kind=='service': status='SLA breach' if i%7==0 else 'Complete'
            if kind=='ledger': status='Reconciled' if i%11 else 'Review'
            if kind=='repair': status=['Pass','Review','Fail','Pass'][i%4];actual=max(0,100-rng.randrange(0,35))
            extra=round(rng.uniform(1,8),1) if kind=='waste' else round((actual/max(target,1))*100,1)
            rows.append(dict(period=period,group=g,item=item,status=status,actual=round(actual,2),cost=round(cost,2),target=round(target,2),units=units,extra=extra))
        # Focus the four KPI tiles on useful, clearly named metrics for each project.
        carddefs={
        'collection':[('Outstanding balance','actual','sum','Open invoice balance'),('Overdue balance','actual','sum','Filter ageing status to isolate overdue'),('Overdue invoices','status','count','Counts selected invoice rows'),('Average days overdue','extra','avg','Synthetic ageing indicator')],
        'profit':[('Job revenue','actual','sum','Revenue on selected job records'),('Direct cost','cost','sum','Direct costs only'),('Gross profit','profit','sum','Revenue less direct costs'),('Gross margin','profitpct','percent','Gross profit divided by revenue')],
        'budget':[('Actual spend','actual','sum','Selected period actual'),('Budget','target','sum','Approved synthetic budget'),('Variance','variance','sum','Budget less actual; positive means under budget'),('Variance %','variancepct','percent','Variance divided by budget')],
        'waste':[('Good output','units','sum','Synthetic output volume'),('Waste cost','wastecost','sum','Material cost allocated to rejected output'),('Reject rate','reject','percent','Reject units divided by total units'),('Work orders','count','count','Selected production orders')],
        'construction':[('Earned value','actual','sum','Value of completed scope'),('Planned value','target','sum','Planned value to date'),('Actual cost','cost','sum','Project cost to date'),('Schedule variance','variance','sum','Earned value less planned value')],
        'demand':[('Actual demand','units','sum','Observed units'),('Forecast','targetunits','sum','Synthetic baseline forecast'),('Forecast error','mape','avg','Mean absolute percentage error'),('At-risk SKU periods','risk','count','Short-cover records')],
        'branch':[('Net sales','actual','sum','Selected branches and periods'),('Sales target','target','sum','Synthetic approved targets'),('Gross profit','profit','sum','Net sales less direct cost'),('Variance to target','variance','sum','Actual less target')],
        'marketing':[('Attributed revenue','actual','sum','Campaign-attributed sales'),('Ad spend','cost','sum','Media spend'),('ROAS','roas','ratio','Attributed revenue divided by spend'),('Conversions','units','sum','Synthetic conversions')],
        'service':[('Service jobs logged','status','count','Selected work orders'),('SLA breach rate','breach','percent','Breach jobs divided by all jobs'),('Service revenue','actual','sum','Recorded work value'),('Service cost','cost','sum','Direct operating cost')],
        'ledger':[('Net balance','actual','sum','Debits positive, credits negative (simplified)'),('Ledger lines','count','count','Selected ledger entries'),('Review lines','status','count','Review status requires reconciliation'),('Period variance','variance','sum','Against synthetic control total')],
        'repair':[('Readiness score','actual','avg','Average scored checks'),('Checks reviewed','count','count','Selected readiness checks'),('Issues','issue','sum','Fail and review flags'),('Fail rate','fail','percent','Failed checks divided by checks')]}
        for r in rows:
            if kind=='profit':r['profit']=round(r['actual']-r['cost'],2);r['profitpct']=None
            if kind=='budget':r['variance']=round(r['target']-r['actual'],2);r['variancepct']=None
            if kind=='waste':r['wastecost']=round(r['cost']*r['extra']/100,2);r['reject']=round(r['extra']/100,4)
            if kind=='construction':r['variance']=round(r['actual']-r['target'],2)
            if kind=='demand':r['targetunits']=r['units']*(.75+rng.random()*.5);r['mape']=abs(r['units']-r['targetunits'])/max(1,r['units']);r['risk']=1 if r['status']=='Short cover' else 0
            if kind=='branch':r['profit']=round(r['actual']-r['cost'],2);r['variance']=round(r['actual']-r['target'],2)
            if kind=='marketing':r['roas']=r['actual']/max(1,r['cost'])
            if kind=='service':r['breach']=1 if r['status']=='SLA breach' else 0
            if kind=='ledger':r['variance']=round(r['actual']-r['target'],2)
            if kind=='repair':r['issue']=1 if r['status'] in ['Review','Fail'] else 0;r['fail']=1 if r['status']=='Fail' else 0
        # MAPE rendered as %, rates use percent-of-numerator; averages calculate separately.
        cards=[]
        for label,key,calc,note in carddefs[kind]:
            if calc=='profit':cards.append({'label':label,'key':'profit','kind':'sum','note':note})
            elif calc=='variance':cards.append({'label':label,'key':'variance','kind':'sum','note':note})
            elif calc=='count':cards.append({'label':label,'key':'actual','kind':'count','note':note})
            elif calc=='avg':cards.append({'label':label,'key':key,'kind':'avg','note':note})
            elif calc=='ratio':cards.append({'label':label,'key':key,'kind':'ratio','denominator':'cost','note':note})
            elif calc=='percent':
                numerator,denom={'profitpct':('profit','actual'),'variancepct':('variance','target'),'reject':('cost','actual'),'breach':('breach','actual'),'fail':('fail','actual')}[key]
                cards.append({'label':label,'key':numerator,'kind':'percent','denominator':denom,'note':note})
            elif calc=='sum':cards.append({'label':label,'key':key,'kind':'sum','note':note})
        columns=[{'key':'period','label':'Period'},{'key':'group','label':group_label},{'key':'item','label':plural[:-1] if plural.endswith('s') else plural},{'key':'status','label':'Status'},{'key':'actual','label':unit,'format':'money'},{'key':'cost','label':'Cost / baseline','format':'money'},{'key':'target','label':'Target','format':'money'},{'key':'units','label':'Units'},{'key':'extra','label':'Indicator %'}]
        data={'slug':slug,'title':title,'groupLabel':group_label,'plural':plural,'rows':rows,'cards':cards,'columns':columns,'chartTitle':kpi,'cardDefs':carddefs[kind]}
        folder=ROOT/slug;folder.mkdir(parents=True,exist_ok=True)
        with (folder/'data.csv').open('w',newline='',encoding='utf-8') as f:
            fields=BASE+sorted(set().union(*(r.keys() for r in rows))-set(BASE));w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
        (folder/'model.json').write_text(json.dumps(data,indent=2)+'\n')
        page=HTML.replace('__TITLE__',title).replace('__group_label__',group_label.lower()).replace('__GROUPS__',''.join(f'<option>{g}</option>' for g in groups)).replace('__STATUSES__',''.join(f'<option>{s}</option>' for s in sorted({r['status'] for r in rows}))).replace('__CHART_TITLE__',kpi).replace('__CARD1__',cards[0]['label']).replace('__DEF1__',cards[0]['note']).replace('__CARD2__',cards[1]['label']).replace('__DEF2__',cards[1]['note']).replace('__CARD3__',cards[2]['label']).replace('__DEF3__',cards[2]['note']).replace('__HEADERS__',''.join(f'<th>{c["label"]}</th>' for c in columns)).replace('__DATA__',json.dumps(data,separators=(',',':'),ensure_ascii=False))
        (folder/'index.html').write_text(page)
        md=f'''# {title}\n\n## Decision supported\n\nReview **{kpi.lower()}** across {group_label.lower()} and periods; investigate **{kpi2.lower()}**.\n\n## Demo and model\n\n- Open `index.html` in a browser for the interactive synthetic-data reference dashboard.\n- `data.csv` is synthetic PKR / unit data and can be refreshed into a report model.\n- `model.json` records the demo rows and metric card definitions.\n- Intended data grain: one row per {plural[:-1].lower() if plural.endswith('s') else plural.lower()} and month.\n- Useful dimensions: period, {group_label.lower()}, item, status.\n- Core measures: total {kpi.lower()}, comparison against target/cost, row-level indicator, selected-period totals.\n\n## Power BI handoff\n\nThe browser dashboard is a working analytics prototype, not a native `.pbip` report. For a Power BI implementation, load `data.csv`, validate its grain and business definitions with the client, create the measures, and build overview, trend and exception pages in Power BI Desktop. Connect a customer source only after field mapping and KPI sign-off.\n\nAll sample data is fictional. This project is not connected to an ERP or customer system.\n'''
        (folder/'README.md').write_text(md)
    print(f'Generated {len(PROJECTS)} analytics demos.')
if __name__=='__main__':main()
